"""Incident report generation (Markdown)."""
from __future__ import annotations

from event_engine.models import CATEGORIES, Event, local_str, utc_iso


def _dur(a: float | None, b: float | None) -> str:
    return f"{b - a:.1f} s" if a and b else "—"


def incident_report_md(ev: Event) -> str:
    L = [f"# VIPER Incident Report — {ev.event_id}", "",
         "> **SIMULATION** — generated by the VIPER R&D demonstrator. No real sensors or facility involved.", "",
         "| Field | Value |", "|---|---|",
         f"| Event ID | {ev.event_id} |",
         f"| Created (UTC) | {ev.created_utc} |",
         f"| Created (local) | {local_str(ev.created_epoch)} |",
         f"| Simulation clock | T+{ev.sim_time:.3f} s |",
         f"| Environment | {ev.environment} |",
         f"| Zone | {ev.zone} |",
         f"| Primary sensor | {ev.sensor_id} ({ev.sensor_type}) |",
         f"| Category | {CATEGORIES.get(ev.category, ev.category)} |",
         f"| Classification | {ev.classification} |",
         f"| Severity | {ev.severity} |",
         f"| Evidence score | {ev.confidence:.2f} (rule-based; not a threat probability) |",
         f"| Verification | {ev.verification_status} |",
         f"| Acknowledgement | {ev.acknowledgement_status} |",
         f"| Resolution | {ev.resolution_status} |",
         f"| Response | {ev.response.get('label', '—')} {('(authorised by ' + ev.response['authorized_by'] + ')') if ev.response else ''} |",
         "", "## Description", "", ev.description, "",
         "## Timing", "",
         f"- Detection latency (first observation → alert): {ev.latency.get('detection_ms', '—')} ms",
         f"- Edge processing (mean): {ev.latency.get('edge_ms', '—')} ms; network (max): {ev.latency.get('network_ms', '—')} ms; fusion compute: {ev.latency.get('fusion_ms', '—')} ms",
         f"- Alert → acknowledgement: {_dur(ev.alert_epoch, ev.ack_epoch)}",
         f"- Alert → resolution: {_dur(ev.alert_epoch, ev.resolved_epoch)}",
         f"- Alert → closure: {_dur(ev.alert_epoch, ev.closed_epoch)}", "",
         "## Lifecycle", "", "| Stage | UTC | Local | Actor | Note |", "|---|---|---|---|---|"]
    for s in ev.lifecycle:
        L.append(f"| {s['stage']} | {s['ts_utc']} | {s.get('ts_local') or local_str(s['ts_epoch'])} | "
                 f"{s['actor']} | {s['note'].replace('|', '/')} |")
    L += ["", "## Classification rule trace", ""] + [f"1. {r}" for r in ev.rules]
    L += ["", "## Contributing observations", "",
          "| Obs | Sensor | Kind | Value | Quality | Sensor ts (edge clock) | Corrected ts | Flags |",
          "|---|---|---|---|---|---|---|---|"]
    for c in ev.contributing:
        L.append(f"| {c['obs_id']} | {c['sensor_id']} | {c['kind']} | {c['value']:g} {c['unit']} | "
                 f"{c['quality']:.2f} | {utc_iso(c['sensor_ts'])} | {utc_iso(c.get('corrected_ts') or c['sensor_ts'])} | "
                 f"{', '.join(c.get('flags', [])) or '—'} |")
    return "\n".join(L) + "\n"
